INSERT INTO "reclamations" VALUES(1677,'03/19/2018','Debt collection','Medical debt','Written notification about debt','This complaint is against [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] and Goodman Frost , PLLC. 

