INSERT INTO "reclamations" VALUES(2123,'01/01/2018','Debt collection','Auto debt','Attempts to collect debt not owed','Complaint against [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] , [COMPTE_ANONYMISÉ] as an Accessory in Committing Fraud against [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] for a debt that he does not owe under terms and conditions under the lease agreement with [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ], [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ], CFO. 

