INSERT INTO "reclamations" VALUES(2455,'10/23/2017','Student loan','Federal student loan servicing','Dealing with your lender or servicer','I left [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] in [COMPTE_ANONYMISÉ] of 2017 and enlisted in the [COMPTE_ANONYMISÉ] and reported on [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ], 2017, my PEBD. 

