INSERT INTO "reclamations" VALUES(2965,'07/26/2017','Credit reporting, credit repair services, or other personal consumer reports','Credit reporting','Incorrect information on your report','Under the new law effective [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ], 2017 any public record data must include name, address, as well as social security number, date of birth in order for it to appear in your credit file. The credit Bureau has not updated the information and per the new law the Bankruptcy listed does not include this information and should be deleted from my credit report','EQUIFAX, INC.',2.0,2.0,'the credit bureau has not updated the information. the information should be deleted from my credit report.');
