INSERT INTO "reclamations" VALUES(3819,'01/23/2017','Credit reporting',NULL,'Incorrect information on credit report','I have told this company on multiple occasions that they have my info mixed up with someone else ''s file : 1. My name is [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] - it ''s never been anything else. Please update and remove the alias. 

