INSERT INTO "reclamations" VALUES(4962,'03/01/2016','Payday loan',NULL,'Can''t contact lender','Today [COMPTE_ANONYMISÉ]/[COMPTE_ANONYMISÉ]/2016 at [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] from Ace cash express called my place of work and told my CSR that I needed to come in and pay on my loan I had with them. I got the message and was embarraseed that my personal business was told to my work associate. I thought that the FDCPA protected consumers like myself from issues like this.','ACE CASH EXPRESS, INC.',2.0,2.0,'Ace cash express called me and told me that I needed to come in and pay on my loan. I thought that the FDCPA protected consumers like myself from issues like this.');
