INSERT INTO "reclamations" VALUES(5776,'06/03/2015','Credit card',NULL,'Billing disputes','Complaint [COMPTE_ANONYMISÉ] : [COMPTE_ANONYMISÉ], Chase Bank, and [COMPTE_ANONYMISÉ] Bank Credit Card Solicitation PracticesBait and Switch Fraud! 

