INSERT INTO "reclamations" VALUES(5796,'05/27/2015','Credit card',NULL,'Other','[COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] [COMPTE_ANONYMISÉ] XXXXCapital One XXXXFor more than [COMPTE_ANONYMISÉ] years I have tried to verify the above mentioned accounts via certified letters and phone correspondence. 

